async def act(page):
    """
    Close any blocking popup, scroll to the bottom of the current page, and navigate to page 2 of the blog feed.

    Notes:
    - Continue from the current UI state (do NOT navigate to '/').
    - Make the navigation-causing click the last action in this function.
    """

    # Attempt to close a visible popup that contains the text "This is a test popup!"
    # The evaluate attempts several heuristics to find and click a close control inside the popup.
    closed = await page.evaluate("""() => {
        try {
            const nodes = Array.from(document.querySelectorAll('*')).filter(n => n.textContent && n.textContent.includes('This is a test popup!'));
            if (nodes.length === 0) return false;
            const container = nodes[0].closest('div, dialog, section, form') || nodes[0].parentElement;
            if (!container) return false;
            const closeSelectors = [
                'button[aria-label*="close" i]',
                'button[aria-label*="Close" i]',
                '.popup-close',
                '.close',
                '.mfp-close',
                '.modal-close',
                '.fancybox-close',
                '.pp-close',
                '.ui-dialog-titlebar-close',
                'button.close',
                'a.close'
            ];
            for (const sel of closeSelectors) {
                const btn = container.querySelector(sel);
                if (btn) { btn.click(); return true; }
            }
            // fallback: find any button or anchor inside container whose text looks like an X
            const btns = Array.from(container.querySelectorAll('button, a'));
            for (const b of btns) {
                const t = (b.textContent || '').trim();
                if (t === '×' || t === 'x' || t === '✖' || t === 'X' || t === '✕') { b.click(); return true; }
            }
            // final fallback: attempt to click at top-right of the container
            const rect = container.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) {
                const clickX = Math.min(window.innerWidth - 1, Math.floor(rect.right) - 6);
                const clickY = Math.max(1, Math.floor(rect.top) + 6);
                const el = document.elementFromPoint(clickX, clickY);
                if (el) { el.click(); return true; }
            }
            return false;
        } catch (e) {
            return false;
        }
    }""")

    # short pause to allow popup dismissal animations
    if closed:
        await page.wait_for_timeout(400)

    # Scroll to the bottom so any lazy-loaded pagination appears
    await page.evaluate("() => { window.scrollTo(0, document.body.scrollHeight); }")
    await page.wait_for_timeout(700)

    # Try accessibility-role-centric selectors inside the main region first
    main = page.get_by_role("main")
    # Candidate link text for page 2 (prefer exact "2")
    candidates = ["2", "Next", "Older posts", "Older Posts", "Older", "Page 2"]

    if await main.count() > 0:
        for name in candidates:
            locator = main.get_by_role("link", name=name)
            if await locator.count() > 0:
                # This click is expected to navigate to the page-2 feed; make it the final action
                await locator.first.click()
                return

    # Fallback: document-level accessibility link lookup
    for name in candidates:
        locator = page.get_by_role("link", name=name)
        if await locator.count() > 0:
            await locator.first.click()
            return

    # Final fallback: evaluate and click an anchor with visible text '2' or typical page-2 href patterns
    clicked = await page.evaluate("""() => {
        const anchors = Array.from(document.querySelectorAll('a'));
        for (const a of anchors) {
            const text = (a.textContent || '').trim();
            const href = (a.getAttribute('href') || '').trim();
            if (text === '2') { a.click(); return true; }
            if (href.includes('page/2') || href.includes('paged=2') || href.includes('page=2') || href.includes('?paged=2') || /[?&]p=2(\b|$)/.test(href)) {
                a.click(); return true;
            }
        }
        return false;
    }""")

    if clicked:
        return

    # Nothing actionable found; finish without further actions
    return

